    public static function register_rest() {
        register_rest_route('bigshor/v1', '/entities', array('methods'=>'GET','callback'=>array(__CLASS__,'rest_entities'),'permission_callback'=>'__return_true'));
        register_rest_route('bigshor/v1', '/entities/(?P<id>\d+)/graph', array('methods'=>'GET','callback'=>array(__CLASS__,'rest_graph'),'permission_callback'=>'__return_true','args'=>array('id'=>array('validate_callback'=>function($v){return absint($v)>0;}))));
        register_rest_route('bigshor/v1', '/commons', array('methods'=>'GET','callback'=>array(__CLASS__,'rest_commons'),'permission_callback'=>'__return_true'));
    }
    public static function rest_entities($request) {
        $limit=max(1,min(100,absint($request->get_param('per_page')?:30)));
        $args=array('post_type'=>'bsw_entity','post_status'=>'publish','posts_per_page'=>$limit,'orderby'=>'title','order'=>'ASC');
        if($request->get_param('type')) $args['tax_query']=array(array('taxonomy'=>'bsw_entity_type','field'=>'slug','terms'=>sanitize_title($request->get_param('type'))));
        $q=new WP_Query($args);$out=array();foreach($q->posts as $p)$out[]=array('id'=>$p->ID,'title'=>get_the_title($p),'url'=>get_permalink($p),'type'=>wp_get_post_terms($p->ID,'bsw_entity_type',array('fields'=>'slugs')));
        return rest_ensure_response(array('count'=>count($out),'entities'=>$out));
    }
    public static function rest_graph($request) {
        $id=absint($request['id']);if(get_post_type($id)!=='bsw_entity'||get_post_status($id)!=='publish')return new WP_Error('not_found','Entity not found.',array('status'=>404));
        return rest_ensure_response(self::collect_graph($id,max(1,min(3,absint($request->get_param('depth')?:2))),60));
    }
    public static function rest_commons($request) {
        $args=array('post_type'=>'attachment','post_status'=>'inherit','posts_per_page'=>max(1,min(60,absint($request->get_param('per_page')?:24))),'orderby'=>'date','order'=>'DESC');
        if($request->get_param('mime'))$args['post_mime_type']=sanitize_text_field($request->get_param('mime'));
        $meta=array();if($request->get_param('rights')==='verified')$meta[]=array('key'=>'_bsw_commons_rights_status','value'=>'verified');
        if($meta)$args['meta_query']=$meta;
        if($request->get_param('collection'))$args['tax_query']=array(array('taxonomy'=>'bsw_commons_collection','field'=>'slug','terms'=>sanitize_title($request->get_param('collection'))));
        $q=new WP_Query($args);$items=array();foreach($q->posts as $p)$items[]=array('id'=>$p->ID,'title'=>get_the_title($p),'url'=>wp_get_attachment_url($p->ID),'mime'=>get_post_mime_type($p->ID),'rights_status'=>get_post_meta($p->ID,'_bsw_commons_rights_status',true),'creator'=>get_post_meta($p->ID,'_bsw_commons_creator',true),'license'=>get_post_meta($p->ID,'_bsw_commons_license',true));
        return rest_ensure_response(array('count'=>count($items),'items'=>$items));
    }
    private static function collect_graph($root,$depth=2,$cap=60) {
        $seen=array($root=>true);$nodes=array();$edges=array();$frontier=array(array('id'=>$root,'level'=>0));
        while($frontier && count($nodes)<$cap){$next=array();foreach($frontier as $item){$id=$item['id'];$p=get_post($id);if(!$p||$p->post_status!=='publish'||$p->post_type!=='bsw_entity')continue;
            $nodes[$id]=array('id'=>$id,'title'=>get_the_title($id),'url'=>get_permalink($id),'level'=>$item['level']);if($item['level'] >= $depth)continue;
            $rows=get_post_meta($id,'_bsw_p3_relationships',true);if(!is_array($rows))continue;foreach($rows as $r){$target=absint($r['target']??0);if(!$target||get_post_type($target)!=='bsw_entity'||get_post_status($target)!=='publish')continue;$label=sanitize_text_field($r['label']??'Related to');$edges[]=array('source'=>$id,'target'=>$target,'label'=>$label);if(!isset($seen[$target])&&count($seen)<$cap){$seen[$target]=true;$next[]=array('id'=>$target,'level'=>$item['level']+1);}}
        }$frontier=$next;}
        $valid=array_fill_keys(array_keys($nodes),true);$edges=array_values(array_filter($edges,function($e)use($valid){return isset($valid[$e['source']])&&isset($valid[$e['target']]);}));return array('root'=>$root,'nodes'=>array_values($nodes),'edges'=>$edges,'truncated'=>count($seen)>=$cap);
    }
    public static function graph_shortcode($atts) {
        $a=shortcode_atts(array('id'=>0,'depth'=>2,'limit'=>40),$atts);$id=absint($a['id']);if(!$id)$id=get_the_ID();if(get_post_type($id)!=='bsw_entity'||get_post_status($id)!=='publish')return '';
        $graph=self::collect_graph($id,max(1,min(3,absint($a['depth']))),max(5,min(60,absint($a['limit']))));if(!$graph['nodes'])return '<p>No published knowledge connections are available.</p>';
        $uid='bsw-graph-'.wp_unique_id();$n=count($graph['nodes']);$w=760;$max_radius=120+(max(1,min(3,absint($a['depth'])))-1)*115;$h=max(450,2*$max_radius+160);$cx=$w/2;$cy=$max_radius+80;$positions=array();$root=$graph['root'];$positions[$root]=array($cx,$cy);
        $groups=array();foreach($graph['nodes'] as $node)if($node['id']!=$root)$groups[$node['level']][]=$node;
        foreach($groups as $level=>$items){$radius=120+($level-1)*115;$count=count($items);foreach($items as $i=>$node){$angle=(-M_PI/2)+(2*M_PI*$i/max(1,$count));$positions[$node['id']]=array($cx+cos($angle)*$radius,$cy+sin($angle)*$radius+($level>1?($level-1)*35:0));}}
        $out='<section id="'.esc_attr($uid).'" class="bsw-p3-graph-wrap"><div class="bsw-p3-graph-head"><h2>Knowledge Graph</h2><div><button type="button" class="bsw-graph-zoom-in">+</button> <button type="button" class="bsw-graph-zoom-out">−</button> <button type="button" class="bsw-graph-reset">Reset</button></div></div><p class="bsw-graph-help">Select an entity to open its profile. This view shows published relationships up to '.absint($a['depth']).' levels.</p><div class="bsw-p3-graph-scroll"><svg class="bsw-p3-graph-svg" viewBox="0 0 '.absint($w).' '.absint($h).'" role="img" aria-label="Interactive network of knowledge entities">';
        foreach($graph['edges'] as $edge){if(!isset($positions[$edge['source']],$positions[$edge['target']]))continue;$p1=$positions[$edge['source']];$p2=$positions[$edge['target']];$out.='<line x1="'.esc_attr($p1[0]).'" y1="'.esc_attr($p1[1]).'" x2="'.esc_attr($p2[0]).'" y2="'.esc_attr($p2[1]).'" stroke="#9aa7b5" stroke-width="2"/><text x="'.esc_attr(($p1[0]+$p2[0])/2).'" y="'.esc_attr(($p1[1]+$p2[1])/2-7).'" class="bsw-graph-edge-label">'.esc_html(wp_trim_words($edge['label'],3,'')).'</text>';}
        foreach($graph['nodes'] as $node){$p=$positions[$node['id']]??array($cx,$cy);$r=$node['id']==$root?30:23;$out.='<a href="'.esc_url($node['url']).'"><circle cx="'.esc_attr($p[0]).'" cy="'.esc_attr($p[1]).'" r="'.$r.'" class="bsw-graph-node '.($node['id']==$root?'is-root':'').'"/><text x="'.esc_attr($p[0]).'" y="'.esc_attr($p[1]+$r+17).'" text-anchor="middle" class="bsw-graph-node-label">'.esc_html(wp_trim_words($node['title'],4,'…')).'</text></a>';}
        $out.='</svg></div><ul class="bsw-graph-accessible">';foreach($graph['nodes'] as $node)$out.='<li><a href="'.esc_url($node['url']).'">'.esc_html($node['title']).'</a></li>';$out.='</ul>';if($graph['truncated'])$out.='<p class="description">Graph display limit reached. Open a connected entity to explore further.</p>';$out.='</section>';
        $out.='<style>#'.esc_attr($uid).' .bsw-p3-graph-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}#'.esc_attr($uid).' .bsw-p3-graph-scroll{overflow:auto;border:1px solid #d9e0e7;border-radius:12px;background:#fbfcfe}#'.esc_attr($uid).' svg{width:100%;min-width:540px;height:auto}#'.esc_attr($uid).' .bsw-graph-node{fill:#e8efff;stroke:#4263a5;stroke-width:2}#'.esc_attr($uid).' .bsw-graph-node.is-root{fill:#244b91;stroke:#17376e}#'.esc_attr($uid).' .bsw-graph-node-label{font:12px sans-serif;fill:#172033}#'.esc_attr($uid).' .bsw-graph-edge-label{font:10px sans-serif;fill:#596579}#'.esc_attr($uid).' .bsw-graph-accessible{columns:2}#'.esc_attr($uid).' button{padding:5px 10px;cursor:pointer}</style>';
        $out.='<script>(function(){var root=document.getElementById('.wp_json_encode($uid).');if(!root)return;var svg=root.querySelector("svg"),scale=1;function apply(){svg.style.transform="scale("+scale+")";svg.style.transformOrigin="top left";}root.querySelector(".bsw-graph-zoom-in").addEventListener("click",function(){scale=Math.min(2,scale+.15);apply();});root.querySelector(".bsw-graph-zoom-out").addEventListener("click",function(){scale=Math.max(.6,scale-.15);apply();});root.querySelector(".bsw-graph-reset").addEventListener("click",function(){scale=1;apply();});})();</script>';
        return $out;
    }


    public static function capture_entity_revision($post_id,$post) {
        if(wp_is_post_revision($post_id)||(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE)||!$post||$post->post_status==='auto-draft')return;
        $keys=array('aliases','external_id','official_url','same_as','language_labels','relationships');$values=array();$has=false;foreach($keys as $key){$value=get_post_meta($post_id,'_bsw_p3_'.$key,true);$values[$key]=$value;if($value!==''&&$value!==array())$has=true;}if(!$has)return;
        $history=get_post_meta($post_id,'_bsw_p3_entity_history',true);if(!is_array($history))$history=array();$latest=$history[0]['values']??null;if($latest===$values)return;array_unshift($history,array('at'=>current_time('mysql'),'by'=>get_current_user_id(),'values'=>$values));update_post_meta($post_id,'_bsw_p3_entity_history',array_slice($history,0,10));
    }
    public static function entity_history_box($post) {
        add_meta_box('bsw_p3_entity_history','BIGSHOR — Structured data history',function($p){$history=get_post_meta($p->ID,'_bsw_p3_entity_history',true);if(!is_array($history)||!$history){echo '<p>No structured-data snapshots recorded yet. Future edits will be recorded here.</p>';return;}echo '<ol>';foreach($history as $i=>$entry){echo '<li>'.esc_html($entry['at']??'').' — '.esc_html(get_the_author_meta('display_name',absint($entry['by']??0))).' <form method="post" action="'.esc_url(admin_url('admin-post.php')).'" style="display:inline"><input type="hidden" name="action" value="bsw_p3_restore_entity_revision"><input type="hidden" name="entity_id" value="'.absint($p->ID).'"><input type="hidden" name="revision_index" value="'.absint($i).'">';wp_nonce_field('bsw_p3_restore_entity_'.$p->ID);submit_button('Restore snapshot','small','submit',false);echo '</form></li>'; }echo '</ol><p class="description">This history covers BIGSHOR structured entity metadata, not the article body. WordPress post revisions continue to handle article text.</p>';},'bsw_entity','normal','default');
    }
    public static function restore_entity_revision() {
        $id=absint($_POST['entity_id']??0);$index=absint($_POST['revision_index']??0);if(!current_user_can('edit_post',$id)||!check_admin_referer('bsw_p3_restore_entity_'.$id))wp_die('Not authorised.');$history=get_post_meta($id,'_bsw_p3_entity_history',true);if(!is_array($history)||!isset($history[$index]['values']))wp_die('Snapshot not found.');foreach($history[$index]['values'] as $key=>$value){if(in_array($key,array('aliases','same_as'),true))$value=sanitize_textarea_field(is_array($value)?implode("\n",$value):(string)$value);elseif($key==='official_url')$value=esc_url_raw($value);update_post_meta($id,'_bsw_p3_'.$key,$value);}wp_safe_redirect(get_edit_post_link($id,'url'));exit;
    }
    public static function media_bulk_actions($actions) { $actions['bsw_commons_rights_pending']='BIGSHOR: Mark rights review pending';$actions['bsw_commons_rehash']='BIGSHOR: Recheck duplicate files';return $actions; }
    public static function handle_media_bulk_actions($redirect,$action,$ids) {
        if(!in_array($action,array('bsw_commons_rights_pending','bsw_commons_rehash'),true))return $redirect;if(!current_user_can('upload_files'))return $redirect;$count=0;foreach((array)$ids as $id){$id=absint($id);if(get_post_type($id)!=='attachment'||!current_user_can('edit_post',$id))continue;if($action==='bsw_commons_rights_pending'){update_post_meta($id,'_bsw_commons_rights_status','needs_review');}else if(class_exists('BSW_Phase3_Extended')){BSW_Phase3_Extended::record_media_fingerprint($id);}$count++;}return add_query_arg('bsw_commons_bulk',$count,$redirect);
    }

    public static function capture_media_revision($id) {
        if(!current_user_can('edit_post',$id))return;$keys=array('creator','source','license','attribution','rights_status');$snapshot=array('at'=>current_time('mysql'),'by'=>get_current_user_id(),'values'=>array());foreach($keys as $key){$meta_key=$key==='rights_status'?'_bsw_commons_rights_status':'_bsw_commons_'.$key;$snapshot['values'][$key]=get_post_meta($id,$meta_key,true);}if(!array_filter($snapshot['values']))return;
        $history=get_post_meta($id,'_bsw_commons_history',true);if(!is_array($history))$history=array();array_unshift($history,$snapshot);update_post_meta($id,'_bsw_commons_history',array_slice($history,0,10));
    }
    public static function media_history_box($post) {
        add_meta_box('bsw_commons_history','BIGSHOR Commons — Metadata history',function($p){$history=get_post_meta($p->ID,'_bsw_commons_history',true);if(!is_array($history)||!$history){echo '<p>No previous metadata snapshots recorded. Changes made after this release will appear here.</p>';return;}echo '<ol>';foreach($history as $i=>$entry){echo '<li>'.esc_html($entry['at']??''). ' — '.esc_html(get_the_author_meta('display_name',absint($entry['by']??0))).' ';echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" style="display:inline"><input type="hidden" name="action" value="bsw_p3_restore_media_revision"><input type="hidden" name="media_id" value="'.absint($p->ID).'"><input type="hidden" name="revision_index" value="'.absint($i).'">';wp_nonce_field('bsw_p3_restore_media_'.$p->ID);submit_button('Restore snapshot','small','submit',false);echo '</form></li>'; }echo '</ol><p class="description">Snapshots cover BIGSHOR Commons attribution and rights metadata, not the original binary file.</p>';},'attachment','side','default');
    }
    public static function restore_media_revision() {
        $id=absint($_POST['media_id']??0);$index=absint($_POST['revision_index']??0);if(!current_user_can('edit_post',$id)||!check_admin_referer('bsw_p3_restore_media_'.$id))wp_die('Not authorised.');$history=get_post_meta($id,'_bsw_commons_history',true);if(!is_array($history)||!isset($history[$index]['values']))wp_die('Snapshot not found.');$values=$history[$index]['values'];foreach(array('creator','source','license','attribution') as $key){$value=$values[$key]??'';if($key==='source')$value=esc_url_raw($value);else $value=sanitize_text_field($value);update_post_meta($id,'_bsw_commons_'.$key,$value);}update_post_meta($id,'_bsw_commons_rights_status',($values['rights_status']??'')==='verified'?'needs_review':sanitize_key($values['rights_status']??'needs_review'));wp_safe_redirect(get_edit_post_link($id,'url'));exit;
    }

    public static function commons_search_shortcode($atts) {
        $a=shortcode_atts(array('limit'=>24,'rights'=>'verified','collection'=>'','mime'=>'image'),$atts);$args=array('post_type'=>'attachment','post_status'=>'inherit','posts_per_page'=>max(1,min(60,absint($a['limit']))),'orderby'=>'date','order'=>'DESC');if($a['mime']!=='all')$args['post_mime_type']=sanitize_text_field($a['mime']);
        $meta=array();if($a['rights']==='verified')$meta[]=array('key'=>'_bsw_commons_rights_status','value'=>'verified');elseif($a['rights']==='pending')$meta[]=array('key'=>'_bsw_commons_rights_status','value'=>'needs_review');if($meta)$args['meta_query']=$meta;
        if($a['collection'])$args['tax_query']=array(array('taxonomy'=>'bsw_commons_collection','field'=>'slug','terms'=>sanitize_title($a['collection'])));
        if(isset($_GET['bsw_commons_q'])&&is_string($_GET['bsw_commons_q']))$args['s']=sanitize_text_field(wp_unslash($_GET['bsw_commons_q']));$q=new WP_Query($args);$out='<form class="bsw-commons-search" method="get"><label>Search Commons <input type="search" name="bsw_commons_q" value="'.esc_attr(sanitize_text_field(wp_unslash($_GET['bsw_commons_q']??''))).'" /></label> <button type="submit">Search</button></form>';
        if(!$q->have_posts())return $out.'<p>No media items found.</p>';$out.='<div class="bsw-commons-results">';foreach($q->posts as $p){$id=$p->ID;$out.='<figure>'.wp_get_attachment_link($id,'medium',false,false).'<figcaption><strong>'.esc_html(get_the_title($id)).'</strong>';$creator=get_post_meta($id,'_bsw_commons_creator',true);$license=get_post_meta($id,'_bsw_commons_license',true);$out.='<br>'.esc_html($creator).' · '.esc_html($license);if(get_post_meta($id,'_bsw_commons_rights_status',true)!=='verified')$out.='<br><em>Rights review pending</em>';$out.='</figcaption></figure>';}$out.='</div><style>.bsw-commons-results{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:18px}.bsw-commons-results img{width:100%;height:160px;object-fit:cover}.bsw-commons-results figure{margin:0}</style>';return $out;
    }
    public static function index_content_media($post_id,$post,$update) {
        if(wp_is_post_revision($post_id)||wp_is_post_autosave($post_id)||!$post||$post->post_type==='attachment'||$post->post_type==='bsw_entity')return;
        $ids=array();$content=(string)$post->post_content;
        if(function_exists('parse_blocks')){ $blocks=parse_blocks($content);$walk=function($items)use(&$walk,&$ids){foreach($items as $b){if(!empty($b['attrs']['id']))$ids[]=absint($b['attrs']['id']);if(!empty($b['attrs']['ids'])&&is_array($b['attrs']['ids']))$ids=array_merge($ids,array_map('absint',$b['attrs']['ids']));if(!empty($b['innerBlocks']))$walk($b['innerBlocks']);}};$walk($blocks); }
        if(preg_match_all('/wp-image-(\d+)/',$content,$m))$ids=array_merge($ids,array_map('absint',$m[1]));$ids=array_values(array_unique(array_filter($ids,function($id){return get_post_type($id)==='attachment';})));
        $old=get_post_meta($post_id,'_bsw_commons_media_ids',true);if(!is_array($old))$old=array();foreach(array_diff($old,$ids) as $mid){$used=get_post_meta($mid,'_bsw_commons_used_in',true);if(is_array($used)){update_post_meta($mid,'_bsw_commons_used_in',array_values(array_diff($used,array($post_id))));}}
        foreach($ids as $mid){$used=get_post_meta($mid,'_bsw_commons_used_in',true);if(!is_array($used))$used=array();$used[]=$post_id;update_post_meta($mid,'_bsw_commons_used_in',array_values(array_unique(array_map('absint',$used))));}update_post_meta($post_id,'_bsw_commons_media_ids',$ids);
    }
    public static function remove_content_media_index($post_id) { $ids=get_post_meta($post_id,'_bsw_commons_media_ids',true);if(is_array($ids))foreach($ids as $mid){$used=get_post_meta($mid,'_bsw_commons_used_in',true);if(is_array($used))update_post_meta($mid,'_bsw_commons_used_in',array_values(array_diff($used,array($post_id))));} }
    public static function commons_usage_shortcode($atts) {
        if(!current_user_can('manage_options'))return '<p>This report is available to site administrators.</p>';$a=shortcode_atts(array('limit'=>50),$atts);$items=get_posts(array('post_type'=>'attachment','post_status'=>'inherit','numberposts'=>max(1,min(200,absint($a['limit']))),'orderby'=>'date','order'=>'DESC'));$out='<div class="bsw-commons-usage"><h2>Commons media usage</h2><table><thead><tr><th>Media</th><th>Rights</th><th>Used in</th></tr></thead><tbody>';foreach($items as $p){$used=get_post_meta($p->ID,'_bsw_commons_used_in',true);if(!is_array($used))$used=array();$out.='<tr><td><a href="'.esc_url(get_edit_post_link($p->ID)).'">'.esc_html(get_the_title($p->ID)).'</a></td><td>'.esc_html(get_post_meta($p->ID,'_bsw_commons_rights_status',true)?:'needs_review').'</td><td>'.count($used);if($used){$out.=' — ';$links=array();foreach(array_slice($used,0,5) as $pid)$links[]='<a href="'.esc_url(get_edit_post_link($pid)).'">'.esc_html(get_the_title($pid)).'</a>';$out.=implode(', ',$links);}$out.='</td></tr>';}$out.='</tbody></table></div>';return $out;
    }
    public static function remove_legacy_schema() { if(class_exists('BSW_Phase3_Knowledge_Commons'))remove_action('wp_head',array('BSW_Phase3_Knowledge_Commons','entity_jsonld'),30); }
    private static function schema_type($id) {
        $terms=wp_get_post_terms($id,'bsw_entity_type',array('fields'=>'slugs'));$slug=!is_wp_error($terms)&&$terms?$terms[0]:'';$map=array('person'=>'Person','people'=>'Person','company'=>'Organization','organisation'=>'Organization','organization'=>'Organization','brand'=>'Brand','place'=>'Place','location'=>'Place','city'=>'City','country'=>'Country','event'=>'Event','book'=>'Book','film'=>'Movie','movie'=>'Movie','school'=>'EducationalOrganization','university'=>'CollegeOrUniversity','institution'=>'EducationalOrganization','award'=>'Award','publication'=>'Periodical','website'=>'WebSite','product'=>'Product','creative-work'=>'CreativeWork');return isset($map[$slug])?$map[$slug]:'Thing';
    }
    public static function entity_jsonld() {
        if(!is_singular('bsw_entity'))return;$id=get_queried_object_id();if(!$id||get_post_status($id)!=='publish')return;$type=self::schema_type($id);$same=get_post_meta($id,'_bsw_p3_same_as',true);$same_urls=array_filter(array_map('esc_url_raw',preg_split('/\r\n|\r|\n/',(string)$same)));$official=esc_url_raw(get_post_meta($id,'_bsw_p3_official_url',true));if($official)$same_urls[]=$official;
        $data=array('@context'=>'https://schema.org','@type'=>$type,'@id'=>get_permalink($id).'#entity','name'=>get_the_title($id),'description'=>wp_strip_all_tags(get_the_excerpt($id)),'url'=>get_permalink($id),'mainEntityOfPage'=>get_permalink($id));if(has_post_thumbnail($id))$data['image']=get_the_post_thumbnail_url($id,'full');$aliases=preg_split('/\r\n|\r|\n/',(string)get_post_meta($id,'_bsw_p3_aliases',true));$aliases=array_values(array_filter(array_map('sanitize_text_field',$aliases)));if($aliases)$data['alternateName']=$aliases;if($same_urls)$data['sameAs']=array_values(array_unique($same_urls));$ext=get_post_meta($id,'_bsw_p3_external_id',true);if($ext)$data['identifier']=array('@type'=>'PropertyValue','propertyID'=>'External identifier','value'=>$ext);$wikidata=esc_url_raw(get_post_meta($id,'_bsw_p3_wikidata_url',true));if($wikidata)$data['sameAs']=array_values(array_unique(array_merge($data['sameAs']??array(),array($wikidata))));
        $relations=get_post_meta($id,'_bsw_p3_relationships',true);if(is_array($relations)){$related=array();foreach($relations as $r){$tid=absint($r['target']??0);if(get_post_type($tid)==='bsw_entity'&&get_post_status($tid)==='publish')$related[]=array('@type'=>'Thing','name'=>get_the_title($tid),'url'=>get_permalink($tid),'additionalType'=>sanitize_text_field($r['label']??'Related entity'));}if($related)$data['subjectOf']=$related;}
        echo "\n<script type=\"application/ld+json\">".wp_json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)."</script>\n";
    }

    public static function wikidata_meta_box($post) {
        $suggestions=get_post_meta($post->ID,'_bsw_p3_wikidata_suggestions',true);if(!is_array($suggestions)||!$suggestions)return;
        add_meta_box('bsw_p3_wikidata_suggestions','Wikidata — External suggestions (review only)',function($p)use($suggestions){
            echo '<p>These values came from Wikidata and are suggestions only. They have not been copied into the article.</p>';
            foreach(array('labels'=>'Labels','descriptions'=>'Descriptions','aliases'=>'Aliases') as $key=>$label){if(empty($suggestions[$key]))continue;echo '<h4>'.esc_html($label).'</h4><ul>';foreach($suggestions[$key] as $lang=>$value){$vals=is_array($value)?$value:array($value);foreach($vals as $v)echo '<li><code>'.esc_html($lang).'</code>: '.esc_html($v).'</li>'; }echo '</ul>';}
            echo '<p><a target="_blank" rel="noopener" href="'.esc_url(get_post_meta($p->ID,'_bsw_p3_wikidata_url',true)).'">Review original Wikidata record</a></p>';
        },'bsw_entity','normal','default');
    }

    public static function admin_menu() { add_submenu_page('edit.php?post_type=bsw_entity','Knowledge Reconciliation','Reconciliation','manage_options','bsw-p3-reconcile',array(__CLASS__,'reconciliation_page'));add_submenu_page('edit.php?post_type=bsw_entity','Knowledge Quality','Quality Reports','manage_options','bsw-p3-quality',array(__CLASS__,'quality_page')); }
    public static function reconciliation_page() {
        if(!current_user_can('manage_options'))return;$results=get_transient('bsw_p3_wikidata_results_'.get_current_user_id());echo '<div class="wrap"><h1>Wikidata Reconciliation</h1><p>Search Wikidata for candidate matches. Selecting a result stores its QID and source URL on the entity; it does not automatically import or overwrite facts.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="bsw_p3_wikidata_search">';wp_nonce_field('bsw_p3_wikidata_search');echo '<label>Search term <input type="search" name="query" required class="regular-text"></label> <label>Entity ID <input type="number" name="entity_id" min="1" required></label> ';submit_button('Search Wikidata','secondary','submit',false);echo '</form>';
        if(is_array($results)&&$results){echo '<h2>Candidate matches</h2><table class="widefat striped"><thead><tr><th>Candidate</th><th>Description</th><th>QID</th><th>Action</th></tr></thead><tbody>';foreach($results as $r){echo '<tr><td>'.esc_html($r['label']).'</td><td>'.esc_html($r['description']).'</td><td><a target="_blank" rel="noopener" href="'.esc_url($r['url']).'">'.esc_html($r['id']).'</a></td><td><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="bsw_p3_wikidata_apply"><input type="hidden" name="entity_id" value="'.absint($r['entity_id']).'"><input type="hidden" name="qid" value="'.esc_attr($r['id']).'"><input type="hidden" name="source_url" value="'.esc_attr($r['url']).'">';wp_nonce_field('bsw_p3_wikidata_apply_'.$r['entity_id']);submit_button('Link this QID','small','submit',false);echo '</form></td></tr>'; }echo '</tbody></table>';}
        echo '<p class="description">External API availability depends on your hosting server and Wikidata service. Search results are cached briefly. Editorial review remains mandatory.</p></div>';
    }
    public static function wikidata_search() {
        if(!current_user_can('manage_options')||!check_admin_referer('bsw_p3_wikidata_search'))wp_die('Not authorised.');$query=sanitize_text_field(wp_unslash($_POST['query']??''));$entity=absint($_POST['entity_id']??0);if(!$query||get_post_type($entity)!=='bsw_entity')wp_die('Enter a valid search and Knowledge Entity ID.');$url=add_query_arg(array('action'=>'wbsearchentities','search'=>$query,'language'=>'en','uselang'=>'en','format'=>'json','limit'=>8),'https://www.wikidata.org/w/api.php');$response=wp_remote_get($url,array('timeout'=>12,'headers'=>array('Accept'=>'application/json','User-Agent'=>'BIGSHOR-Wiki/17.0 (knowledge reconciliation)')));$rows=array();if(!is_wp_error($response)&&wp_remote_retrieve_response_code($response)===200){$json=json_decode(wp_remote_retrieve_body($response),true);foreach(($json['search']??array()) as $r){$qid=sanitize_text_field($r['id']??'');if(!preg_match('/^Q[1-9][0-9]*$/',$qid))continue;$rows[]=array('id'=>$qid,'label'=>sanitize_text_field($r['label']??''),'description'=>sanitize_text_field($r['description']??''),'url'=>'https://www.wikidata.org/wiki/'.$qid,'entity_id'=>$entity);}}set_transient('bsw_p3_wikidata_results_'.get_current_user_id(),$rows,5*MINUTE_IN_SECONDS);wp_safe_redirect(admin_url('edit.php?post_type=bsw_entity&page=bsw-p3-reconcile'));exit;
    }
    public static function wikidata_apply() {
        $id=absint($_POST['entity_id']??0);if(!current_user_can('edit_post',$id)||!check_admin_referer('bsw_p3_wikidata_apply_'.$id))wp_die('Not authorised.');$qid=sanitize_text_field(wp_unslash($_POST['qid']??''));$source='https://www.wikidata.org/wiki/'.$qid;if(!preg_match('/^Q[1-9][0-9]*$/',$qid)||get_post_type($id)!=='bsw_entity')wp_die('Invalid Wikidata identifier.');update_post_meta($id,'_bsw_p3_external_id',$qid);update_post_meta($id,'_bsw_p3_wikidata_url',$source);update_post_meta($id,'_bsw_p3_wikidata_linked_at',current_time('mysql'));update_post_meta($id,'_bsw_p3_wikidata_linked_by',get_current_user_id());
        $api=add_query_arg(array('action'=>'wbgetentities','ids'=>$qid,'props'=>'labels|descriptions|aliases','languages'=>'en|ar|hi','format'=>'json'),'https://www.wikidata.org/w/api.php');$response=wp_remote_get($api,array('timeout'=>12,'headers'=>array('Accept'=>'application/json','User-Agent'=>'BIGSHOR-Wiki/17.0 (knowledge reconciliation)')));
        if(!is_wp_error($response)&&wp_remote_retrieve_response_code($response)===200){$payload=json_decode(wp_remote_retrieve_body($response),true);$entity=$payload['entities'][$qid]??array();$suggestions=array('labels'=>array(),'descriptions'=>array(),'aliases'=>array());foreach(array('labels','descriptions') as $kind)foreach(($entity[$kind]??array()) as $lang=>$item){if(isset($item['value']))$suggestions[$kind][sanitize_key($lang)]=sanitize_text_field($item['value']);}foreach(($entity['aliases']??array()) as $lang=>$items){foreach($items as $item)if(isset($item['value']))$suggestions['aliases'][sanitize_key($lang)][]=sanitize_text_field($item['value']);}update_post_meta($id,'_bsw_p3_wikidata_suggestions',$suggestions);update_post_meta($id,'_bsw_p3_wikidata_suggestions_at',current_time('mysql'));}
        wp_safe_redirect(get_edit_post_link($id,'url'));exit;
    }
    public static function quality_page() {
        if(!current_user_can('manage_options'))return;$entities=get_posts(array('post_type'=>'bsw_entity','post_status'=>array('publish','draft','pending'),'numberposts'=>500,'fields'=>'ids'));$missing=array();$orphan=array();$unlinked=0;foreach($entities as $id){$has_source=(bool)get_post_meta($id,'_bsw_p3_external_id',true);$same=get_post_meta($id,'_bsw_p3_same_as',true);$rels=get_post_meta($id,'_bsw_p3_relationships',true);if(!$has_source&&!$same)$unlinked++;if(!$has_source&&!$same&&!$rels)$orphan[]=$id;if(!get_post_meta($id,'_bsw_p3_official_url',true)&&!$same)$missing[]=$id;}
        $media=get_posts(array('post_type'=>'attachment','post_status'=>'inherit','numberposts'=>500,'fields'=>'ids'));$pending=0;$unused=0;foreach($media as $mid){if(get_post_meta($mid,'_bsw_commons_rights_status',true)!=='verified')$pending++;$used=get_post_meta($mid,'_bsw_commons_used_in',true);if(!is_array($used)||!$used)$unused++;}
        echo '<div class="wrap"><h1>Knowledge Quality Reports</h1><div class="notice notice-info"><p>Counts below cover at most 500 entities and 500 media items per report run; they are diagnostic indicators, not an assertion that missing external identifiers make an entity inaccurate.</p></div><h2>Knowledge Entities</h2><ul><li>Entities scanned: '.count($entities).'</li><li>Without external identifier or sameAs URL: '.$unlinked.'</li><li>Without official URL and sameAs: '.count($missing).'</li><li>Potential orphan entities (no source links and no relationships): '.count($orphan).'</li></ul>';if($orphan){echo '<h3>Potential orphan records</h3><ul>';foreach(array_slice($orphan,0,30) as $id)echo '<li><a href="'.esc_url(get_edit_post_link($id)).'">'.esc_html(get_the_title($id)).'</a></li>';echo '</ul>';}
        echo '<h2>Potential duplicate entities — manual merge review</h2><p>Merging preserves the source record as a private redirect record and transfers its title into the survivor aliases. Review evidence before proceeding.</p>';
        $dupes=class_exists('BSW_Phase3_Extended')?BSW_Phase3_Extended::find_entity_duplicates(30):array();
        if(!$dupes) echo '<p>No exact-title or external-ID duplicate candidates found in the scanned sample.</p>';
        foreach($dupes as $group){if(count($group['ids'])<2)continue;$src=absint($group['ids'][1]);$dst=absint($group['ids'][0]);echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" style="border:1px solid #ccd0d4;padding:12px;margin:10px 0;background:#fff"><input type="hidden" name="action" value="bsw_p3_merge_entity"><input type="hidden" name="source_id" value="'.$src.'"><input type="hidden" name="target_id" value="'.$dst.'">';wp_nonce_field('bsw_p3_merge_'.$src);echo '<strong>'.esc_html($group['reason']).'</strong><p>Keep: <a href="'.esc_url(get_edit_post_link($dst)).'">'.esc_html(get_the_title($dst)).' (#'.$dst.')</a><br>Merge and preserve as private: <a href="'.esc_url(get_edit_post_link($src)).'">'.esc_html(get_the_title($src)).' (#'.$src.')</a></p>';submit_button('Merge second record into first','delete','submit',false,array('onclick'=>"return confirm('This will make the source record private and redirect its public URL. Continue?');"));echo '</form>';}
        echo '<h2>Commons</h2><ul><li>Media scanned: '.count($media).'</li><li>Rights review pending: '.$pending.'</li><li>Not yet indexed as used in content: '.$unused.'</li></ul><p>Media usage indexing starts when content is saved after this release is activated. Historical content may need to be resaved to populate usage records.</p></div>';
    }
    public static function merge_entity() {
        $source=absint($_POST['source_id']??0);$target=absint($_POST['target_id']??0);if(!current_user_can('manage_options')||!check_admin_referer('bsw_p3_merge_'.$source))wp_die('Not authorised.');if(!$source||!$target||$source===$target||get_post_type($source)!=='bsw_entity'||get_post_type($target)!=='bsw_entity'||get_post_status($target)!=='publish')wp_die('Choose a valid source entity and published surviving entity.');
        $aliases=get_post_meta($target,'_bsw_p3_aliases',true);$aliases=preg_split('/\r\n|\r|\n/',(string)$aliases);$aliases[] = get_the_title($source);$aliases=array_values(array_unique(array_filter(array_map('sanitize_text_field',$aliases))));update_post_meta($target,'_bsw_p3_aliases',implode("\n",$aliases));
        $source_rels=get_post_meta($source,'_bsw_p3_relationships',true);$target_rels=get_post_meta($target,'_bsw_p3_relationships',true);if(!is_array($target_rels))$target_rels=array();if(is_array($source_rels))$target_rels=array_merge($target_rels,$source_rels);$clean=array();foreach($target_rels as $r){$tid=absint($r['target']??0);if($tid===$source)$tid=$target;if($tid&&$tid!==$target&&get_post_type($tid)==='bsw_entity')$clean[]=array('label'=>sanitize_text_field($r['label']??'Related to'),'target'=>$tid);}update_post_meta($target,'_bsw_p3_relationships',$clean);
        $all=get_posts(array('post_type'=>'bsw_entity','post_status'=>array('publish','draft','pending','private'),'numberposts'=>-1,'fields'=>'ids'));foreach($all as $eid){if($eid===$source)continue;$rows=get_post_meta($eid,'_bsw_p3_relationships',true);if(!is_array($rows))continue;$changed=false;foreach($rows as &$r)if(absint($r['target']??0)===$source){$r['target']=$target;$changed=true;}unset($r);if($changed){$rows=array_values(array_filter($rows,function($r)use($eid){return absint($r['target']??0)!==$eid;}));update_post_meta($eid,'_bsw_p3_relationships',$rows);}}
        update_post_meta($source,'_bsw_p3_merged_into',$target);update_post_meta($source,'_bsw_p3_merged_at',current_time('mysql'));update_post_meta($source,'_bsw_p3_merged_by',get_current_user_id());wp_update_post(array('ID'=>$source,'post_status'=>'publish','post_content'=>'This entity record has been merged into another BIGSHOR Knowledge Entity.'));$relation_ids=get_posts(array('post_type'=>'bsw_relation','post_status'=>'private','numberposts'=>-1,'fields'=>'ids','meta_query'=>array('relation'=>'OR',array('key'=>'_bsw_rel_source','value'=>$source),array('key'=>'_bsw_rel_target','value'=>$source))));foreach($relation_ids as $rid){if(absint(get_post_meta($rid,'_bsw_rel_source',true))===$source)update_post_meta($rid,'_bsw_rel_source',$target);if(absint(get_post_meta($rid,'_bsw_rel_target',true))===$source)update_post_meta($rid,'_bsw_rel_target',$target);}
        wp_safe_redirect(add_query_arg('bsw_merged','1',get_edit_post_link($target,'url')));exit;
    }
    public static function merged_entity_redirect() { if(!is_singular('bsw_entity'))return;$id=get_queried_object_id();$target=absint(get_post_meta($id,'_bsw_p3_merged_into',true));if($target&&get_post_status($target)==='publish'){wp_safe_redirect(get_permalink($target),301);exit;} }
}
BSW_Phase3_Completion::boot();
}
